contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address callee, bytes memory data) public {
        require(callee == address(this));
        bool reverted;
        c.forward(callee, data); if (__ESBMC_reverted()) return;
        reverted = false;
        assert(!reverted);
    }

    fallback() external payable {
        require(msg.sender == address(c));
    }

    receive() external payable {}
}

